use std::collections::HashSet;

use serde_json::{Value, json};

use crate::error::GatewayError;

pub(crate) const NAMESPACE: &str = "collaboration";
const PLAINTEXT_NAMESPACE: &str = "codex_mixin_collaboration";

fn is_message_tool(namespace: Option<&str>, name: &str) -> bool {
    namespace == Some(NAMESPACE) && matches!(name, "spawn_agent" | "send_message" | "followup_task")
}

/// Only call this for arguments generated by a known plaintext protocol.
/// Missing encryption metadata on a native Responses call is not plaintext evidence.
pub(crate) fn mark_plaintext_call(item: &mut Value) {
    if item.get("type").and_then(Value::as_str) == Some("function_call")
        && is_message_tool(
            item.get("namespace").and_then(Value::as_str),
            item.get("name").and_then(Value::as_str).unwrap_or(""),
        )
        && item
            .get("encrypted_function_args")
            .is_none_or(Value::is_null)
    {
        item["encrypted_function_args"] = json!([]);
    }
}

/// Restore only calls generated through our ordinary, unencrypted tool namespace.
/// Native collaboration calls, including legacy ciphertext without metadata, stay opaque.
pub(crate) fn restore_event(payload: &mut Value) -> Result<(), GatewayError> {
    if let Some(item) = payload.get_mut("item") {
        restore_call(item)?;
    }
    if let Some(output) = payload
        .get_mut("response")
        .and_then(|response| response.get_mut("output"))
        .and_then(Value::as_array_mut)
    {
        for item in output {
            restore_call(item)?;
        }
    }
    Ok(())
}

fn restore_call(item: &mut Value) -> Result<(), GatewayError> {
    if item.get("type").and_then(Value::as_str) != Some("function_call")
        || item.get("namespace").and_then(Value::as_str) != Some(PLAINTEXT_NAMESPACE)
    {
        return Ok(());
    }
    if is_message_tool(
        Some(NAMESPACE),
        item.get("name").and_then(Value::as_str).unwrap_or(""),
    ) && item
        .get("encrypted_function_args")
        .is_some_and(|args| !args.is_null() && args.as_array().is_none_or(|args| !args.is_empty()))
    {
        return Err(GatewayError::Upstream(
            "encrypted arguments returned for a plaintext collaboration tool".to_owned(),
        ));
    }
    item["namespace"] = Value::String(NAMESPACE.to_owned());
    mark_plaintext_call(item);
    Ok(())
}

pub(crate) fn prepare_schema(schema: &mut Value, namespace: Option<&str>, name: &str) {
    if is_message_tool(namespace, name)
        && let Some(message) = schema
            .pointer_mut("/properties/message")
            .and_then(Value::as_object_mut)
    {
        message.remove("encrypted");
    }
}

/// Save only changed fields, never a clone of the conversation or tool arguments.
pub(crate) struct RequestRestore {
    fields: Vec<(String, &'static str, Value)>,
    messages: Vec<(usize, Value)>,
    active: bool,
}

impl RequestRestore {
    pub(crate) fn active(&self) -> bool {
        self.active
    }
}

type InheritedCollaboration<'a> = (&'a [Value], Option<&'a Value>);

fn declared_tools<'a>(
    body: &'a Value,
    inherited: Option<InheritedCollaboration<'a>>,
) -> impl Iterator<Item = &'a Value> {
    body.get("tools")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .chain(inherited.into_iter().flat_map(|(_, tool)| tool))
        .chain(
            body.get("input")
                .and_then(Value::as_array)
                .into_iter()
                .flatten()
                .chain(inherited.into_iter().flat_map(|(input, _)| input))
                .filter(|item| {
                    matches!(
                        item.get("type").and_then(Value::as_str),
                        Some("additional_tools" | "tool_search_output")
                    )
                })
                .flat_map(|item| {
                    item.get("tools")
                        .and_then(Value::as_array)
                        .into_iter()
                        .flatten()
                }),
        )
}

pub(crate) fn prepare_request(
    body: &mut Value,
    inherited: Option<InheritedCollaboration<'_>>,
) -> Result<RequestRestore, GatewayError> {
    let mut active = inherited.is_some();
    let mut collision = false;
    for tool in declared_tools(body, None) {
        let name = tool.get("name").and_then(Value::as_str);
        active |= tool.get("type").and_then(Value::as_str) == Some("namespace")
            && name == Some(NAMESPACE);
        collision |= name == Some(PLAINTEXT_NAMESPACE);
    }
    let mut alias_history = body
        .get("input")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter(|item| item.get("namespace").and_then(Value::as_str) == Some(PLAINTEXT_NAMESPACE))
        .peekable();
    if active && !collision && alias_history.peek().is_some() {
        // Only index the adapted tool declarations when the request replays the alias.
        let adapted_function_names: HashSet<_> = declared_tools(body, inherited)
            .filter(|tool| {
                tool.get("type").and_then(Value::as_str) == Some("namespace")
                    && tool.get("name").and_then(Value::as_str) == Some(NAMESPACE)
            })
            .filter_map(|tool| tool.get("tools").and_then(Value::as_array))
            .flatten()
            .filter(|tool| tool.get("type").and_then(Value::as_str) == Some("function"))
            .filter_map(|tool| tool.get("name").and_then(Value::as_str))
            .collect();
        collision = alias_history.any(|item| {
            let name = item.get("name").and_then(Value::as_str);
            let encrypted = item.get("encrypted_function_args").is_some_and(|args| {
                !args.is_null() && args.as_array().is_none_or(|args| !args.is_empty())
            });
            item.get("type").and_then(Value::as_str) != Some("function_call")
                || encrypted
                || name.is_none_or(|name| !adapted_function_names.contains(name))
        });
    }
    if active && collision {
        return Err(GatewayError::BadRequest(
            "collaboration compatibility namespace is already in use".to_owned(),
        ));
    }
    if let Some(input) = body.get("input").and_then(Value::as_array) {
        for item in input {
            if item.get("type").and_then(Value::as_str) == Some("agent_message") {
                validate_plaintext_message(item)?;
            }
        }
    }
    let mut saved = RequestRestore {
        fields: Vec::new(),
        messages: Vec::new(),
        active,
    };
    if active && let Some(tools) = body.get_mut("tools").and_then(Value::as_array_mut) {
        prepare_tools(tools, "/tools", &mut saved);
    }
    if let Some(input) = body.get_mut("input").and_then(Value::as_array_mut) {
        for (index, item) in input.iter_mut().enumerate() {
            if item.get("type").and_then(Value::as_str) == Some("agent_message") {
                if let Some(message) = plaintext_message(item)? {
                    saved
                        .messages
                        .push((index, std::mem::replace(item, message)));
                }
                continue;
            }
            if !active {
                continue;
            }
            if matches!(
                item.get("type").and_then(Value::as_str),
                Some("additional_tools" | "tool_search_output")
            ) && let Some(tools) = item.get_mut("tools").and_then(Value::as_array_mut)
            {
                prepare_tools(tools, &format!("/input/{index}/tools"), &mut saved);
            } else if item.get("type").and_then(Value::as_str) == Some("function_call")
                && item.get("namespace").and_then(Value::as_str) == Some(NAMESPACE)
                && (!is_message_tool(
                    Some(NAMESPACE),
                    item.get("name").and_then(Value::as_str).unwrap_or(""),
                ) || item
                    .get("encrypted_function_args")
                    .and_then(Value::as_array)
                    .is_some_and(Vec::is_empty))
            {
                // Replay known plaintext/control calls under their advertised namespace.
                // Calls without transport provenance may contain genuine ciphertext.
                rename_namespace(item, &format!("/input/{index}"), "namespace", &mut saved);
            }
        }
    }
    Ok(saved)
}

fn validate_plaintext_message(item: &Value) -> Result<(), GatewayError> {
    let Some(content) = item.get("content").and_then(Value::as_array) else {
        return Err(GatewayError::BadRequest(
            "agent_message missing content".to_owned(),
        ));
    };
    if content
        .iter()
        .any(|part| part.get("type").and_then(Value::as_str) != Some("input_text"))
    {
        return Ok(());
    }
    if content.is_empty() {
        return Err(GatewayError::BadRequest(
            "agent_message has no plaintext content".to_owned(),
        ));
    }
    for key in ["author", "recipient"] {
        if item.get(key).and_then(Value::as_str).is_none() {
            return Err(GatewayError::BadRequest(format!(
                "agent_message missing {key}"
            )));
        }
    }
    if content
        .iter()
        .any(|part| part.get("text").and_then(Value::as_str).is_none())
    {
        return Err(GatewayError::BadRequest(
            "agent_message input_text missing text".to_owned(),
        ));
    }
    Ok(())
}

fn plaintext_message(item: &Value) -> Result<Option<Value>, GatewayError> {
    let Some(content) = item.get("content").and_then(Value::as_array) else {
        return Ok(None);
    };
    if content
        .iter()
        .any(|part| part.get("type").and_then(Value::as_str) != Some("input_text"))
    {
        // An encrypted/mixed native envelope must remain byte-for-byte opaque.
        return Ok(None);
    }
    let author = item
        .get("author")
        .and_then(Value::as_str)
        .ok_or_else(|| GatewayError::BadRequest("agent_message missing author".to_owned()))?;
    let recipient = item
        .get("recipient")
        .and_then(Value::as_str)
        .ok_or_else(|| GatewayError::BadRequest("agent_message missing recipient".to_owned()))?;
    let mut text = format!("[Agent message from {author} to {recipient}]\n");
    for (index, part) in content.iter().enumerate() {
        if index > 0 {
            text.push('\n');
        }
        let part = part.get("text").and_then(Value::as_str).ok_or_else(|| {
            GatewayError::BadRequest("agent_message input_text missing text".to_owned())
        })?;
        text.push_str(part);
    }
    Ok(Some(
        json!({"type":"message", "role":"user", "content":[{"type":"input_text", "text":text}]}),
    ))
}

fn rename_namespace(item: &mut Value, path: &str, key: &'static str, saved: &mut RequestRestore) {
    if let Some(value) = item.get_mut(key) {
        let original = std::mem::replace(value, Value::String(PLAINTEXT_NAMESPACE.to_owned()));
        saved.fields.push((path.to_owned(), key, original));
    }
}

fn prepare_tools(tools: &mut [Value], prefix: &str, saved: &mut RequestRestore) {
    for (index, tool) in tools.iter_mut().enumerate() {
        if tool.get("type").and_then(Value::as_str) != Some("namespace")
            || tool.get("name").and_then(Value::as_str) != Some(NAMESPACE)
        {
            continue;
        }
        // OpenAI's reserved namespace requires the exact encrypted schema.
        // Ordinary tools let the backend generate plaintext before Codex receives it.
        rename_namespace(tool, &format!("{prefix}/{index}"), "name", saved);
        let Some(nested) = tool.get_mut("tools").and_then(Value::as_array_mut) else {
            continue;
        };
        for (nested_index, function) in nested.iter_mut().enumerate() {
            if function.get("type").and_then(Value::as_str) != Some("function")
                || !is_message_tool(
                    Some(NAMESPACE),
                    function.get("name").and_then(Value::as_str).unwrap_or(""),
                )
            {
                continue;
            }
            for schema in ["parameters", "input_schema", "inputSchema"] {
                if let Some(message) = function
                    .get_mut(schema)
                    .and_then(|schema| schema.pointer_mut("/properties/message"))
                    .and_then(Value::as_object_mut)
                    && let Some(annotation) = message.remove("encrypted")
                {
                    saved.fields.push((
                        format!(
                            "{prefix}/{index}/tools/{nested_index}/{schema}/properties/message"
                        ),
                        "encrypted",
                        annotation,
                    ));
                }
            }
        }
    }
}

pub(crate) fn restore_request(body: &mut Value, saved: RequestRestore) {
    if let Some(input) = body.get_mut("input").and_then(Value::as_array_mut) {
        for (index, value) in saved.messages {
            if let Some(item) = input.get_mut(index) {
                *item = value;
            }
        }
    }
    for (path, key, value) in saved.fields.into_iter().rev() {
        if let Some(fields) = body.pointer_mut(&path).and_then(Value::as_object_mut) {
            fields.insert(key.to_owned(), value);
        }
    }
}

